// Apply migrations. With a file name, applies exactly that one (a release
// runs each migration once per site, guarded by a chant effect receipt).
// Without one, applies every migration not yet recorded in this database,
// which is what the box does against the dev data each time the app starts.
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { open } from './db.js';

const dir = join(import.meta.dirname, 'migrations');
const db = open();
db.exec('CREATE TABLE IF NOT EXISTS schema_migrations (file TEXT PRIMARY KEY, applied_at TEXT NOT NULL)');
const done = new Set(db.prepare('SELECT file FROM schema_migrations').all().map((r) => r.file));
const wanted = process.argv[2] ? [process.argv[2]] : readdirSync(dir).filter((f) => f.endsWith('.sql')).sort();

for (const file of wanted) {
  if (done.has(file)) {
    console.log(`skip ${file} (already applied)`);
    continue;
  }
  db.exec('BEGIN');
  try {
    db.exec(readFileSync(join(dir, file), 'utf8'));
    db.prepare('INSERT INTO schema_migrations (file, applied_at) VALUES (?, ?)').run(file, new Date().toISOString());
    db.exec('COMMIT');
    console.log(`applied ${file}`);
  } catch (error) {
    db.exec('ROLLBACK');
    console.error(`failed ${file}: ${error.message}`);
    process.exit(1);
  }
}

