import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { open } from './db.js';

const port = Number(process.env.PORT ?? 3000);
const revision = process.env.APP_REVISION ?? 'dev';
const db = open();

const json = (res, status, body) => {
  res.writeHead(status, { 'content-type': 'application/json' });
  res.end(JSON.stringify(body));
};

async function body(req) {
  const chunks = [];
  for await (const c of req) chunks.push(c);
  return chunks.length ? JSON.parse(Buffer.concat(chunks).toString('utf8')) : {};
}

const routes = {
  'GET /health': (req, res) => {
    let database = 'healthy';
    try { db.prepare('SELECT 1 FROM notes LIMIT 1').all(); } catch (error) { database = error.message; }
    json(res, database === 'healthy' ? 200 : 503, { status: database === 'healthy' ? 'healthy' : 'unhealthy', revision, services: { web: 'healthy', database } });
  },
  'GET /api/notes': (req, res) => json(res, 200, db.prepare('SELECT * FROM notes ORDER BY id DESC').all()),
  'POST /api/notes': async (req, res) => {
    const { body: text } = await body(req);
    if (!text || !String(text).trim()) return json(res, 400, { error: 'body is required' });
    const row = db.prepare('INSERT INTO notes (body) VALUES (?) RETURNING *').get(String(text).trim());
    json(res, 201, row);
  },
};

createServer(async (req, res) => {
  const path = new URL(req.url, 'http://x').pathname;
  try {
    const route = routes[`${req.method} ${path}`];
    if (route) return await route(req, res);
    if (req.method === 'GET' && path === '/') {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      return res.end(await readFile(join(import.meta.dirname, 'public', 'index.html')));
    }
    json(res, 404, { error: 'not found' });
  } catch (error) {
    console.error(error);
    json(res, 500, { error: error.message });
  }
}).listen(port, '127.0.0.1', () => console.log(`app listening on http://127.0.0.1:${port} (revision ${revision})`));

