import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { spawn, execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const root = join(import.meta.dirname, '..');
const data = mkdtempSync(join(tmpdir(), 'app-test-'));
const port = 20000 + Math.floor(Math.random() * 20000);
const env = { ...process.env, APP_DATA: data, PORT: String(port), NODE_NO_WARNINGS: '1' };
const url = `http://127.0.0.1:${port}`;
let server;

before(async () => {
  execFileSync(process.execPath, ['migrate.js'], { cwd: root, env });
  server = spawn(process.execPath, ['server.js'], { cwd: root, env, stdio: 'ignore' });
  for (let i = 0; i < 50; i++) {
    try { if ((await fetch(`${url}/health`)).ok) return; } catch {}
    await new Promise((r) => setTimeout(r, 100));
  }
  throw new Error('server did not start');
});

after(() => {
  server?.kill();
  rmSync(data, { recursive: true, force: true });
});

test('health reports healthy', async () => {
  const health = await (await fetch(`${url}/health`)).json();
  assert.equal(health.status, 'healthy');
});

test('a note can be added and listed', async () => {
  const created = await fetch(`${url}/api/notes`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ body: 'hello' }) });
  assert.equal(created.status, 201);
  const notes = await (await fetch(`${url}/api/notes`)).json();
  assert.equal(notes[0].body, 'hello');
});

