files.decisions/decision.kind.mjs:
// The decision record kind (#2555).
//
// chant workspace records --kind decisions/decision.kind.mjs --current --json
//
// recordKind is a copy of docs/design/decisions/decision.kind.mjs in the chant
// repo, with decision.schema.json beside it, so a workspace made from this one
// reads its decisions without the chant repo. chant's
// test/reference-workspace.test.ts fails when this kind's data or the schema
// drifts from chant's. commitJoins below is chud's own.
//
// recordKind is chant main's as of INTENTIUS/chant#2676 and #2675: `reviews`
// names the verdicts field, which `chant workspace records review` appends to.
// chant 0.85.0 and earlier refuse a kind with `reviews` (kind-invalid), so this
// kind needs chant 0.86.0 or later.
//
// decision.schema.json is chant-v0.90.0's, with the source fields #2708 added
// (via, client, harness, model, session, turns, transcript). The kind does not
// yet declare chant-v0.90.0's `source: { field: "source" }`, which is how
// `chant serve mcp` knows to stamp a new record's source with via "mcp" and
// the client (INTENTIUS/chant#2707): chant before 0.90.0 refuses a kind with
// `source` (kind-invalid), and delivery/ installs chant ^0.86.0, which chud's
// design app writes records with. The studio smoke adds it in the repo it
// makes for its MCP round trip (docs/smoke-claims.md, section 28).
import { execFileSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

export const recordKind = {
  name: "decision",
  location: { dir: ".", match: "^[a-z][a-z0-9]{0,15}-[0-9]{3,}-.+\\.md$" },
  format: "markdown-front-matter",
  schema: { id: "urn:intentius:chant:decision:1", path: "decision.schema.json" },
  idField: "id",
  stateField: "state",
  states: ["proposed", "decided", "ratified", "superseded", "withdrawn"],
  // Sealed once reached (#2555).
  closedStates: ["ratified", "superseded"],
  supersedes: { field: "supersedes", key: "decision" },
  // A supersedes link takes effect under an equal or stricter approval rule
  // (#2524 D4): from a record ranked above 0 and at least as high as the one it
  // names. A decided record supersedes a decided or proposed one, a ratified
  // record supersedes any, and a proposed or withdrawn record none.
  approval: { proposed: 0, withdrawn: 0, decided: 1, ratified: 2, superseded: 2 },
  // Evidence entries with a path pin a workspace file by the hash of its bytes (#2549).
  pins: { field: "evidence" },
  // member:<name> and path:<path> entries are the record's links in workspace graph (#2549).
  constrains: { field: "constrains" },
  // Verdicts, and the field naming the decider, for each record's digest and
  // quorum (#2671, #2672).
  reviews: { field: "reviews", decider: "decided_by" },
};

// How `chant workspace graph --intent <path> --kind decisions/decision.kind.mjs`
// joins a commit to the unit of work that made it, in the function form of
// chant's commitJoins (chant #2651, #2656). chant calls it once for each commit
// that touched the region, as commitJoins(commit, context): commit is { sha,
// subject, body, author: { name, email }, date, trailers: { key: [values] } }
// and context is { read(path), list(dir), at }, where read gives a file's text
// and list a directory's entries in the tree the graph reads, from the
// workspace root (list is chant #2663, in 0.86.0).
//
// A unit is a chant work item, work/W-NNN-<slug>.md, with chud's fields under
// x-chud (jhgaylor/chud#78). The join comes from the records first: the work
// item whose x-chud.result.commit is the commit is the unit that made it, its
// x-chud.contract (or driver) the contract, and its x-chud.evidence the
// evidence it cites, each evidence record (design/evidence/<hash>.json) adding
// its fields. That needs context.list, to find the work items. A commit no work
// item names (a unit's open and close commits, its kept not_done snapshot, a
// repo on the old layout, a chant without list) is joined by its trailers as
// the data form joined it (jhgaylor/chud#84): Chud-Unit, Chud-Contract
// (Chud-Driver for a split) and one Chud-Evidence per cited evidence record
// beside Chud-Author. A W-NNN unit's fields come from its work item, a U-NNNN
// unit's from design/units/<id>.json; a contract is markdown, so it is joined
// by id alone. Chud-Author is the authorship trailer. The unit trailers stay on
// unit commits for one release, and can go once every commit a unit makes is
// named by its record.
//
// It also reports one finding, contract-moved, in chud's namespace:
// plugin:chud:contract-moved. chant namespaces a kind's findings by the kind's
// name, which is "decision" here, unless the kind file names them with
// commitJoinsName (chant #2663, after 0.85.0), which this one does. chant
// 0.85.0 does not read commitJoinsName and accepts only
// plugin:decision:contract-moved, so the hook reports the code the running
// chant accepts (findingCode below). The rule: a unit
// commit whose contract is constrained by a decision in force at that commit
// (the decision is in the tree, and no decision in the tree supersedes it),
// where an earlier commit of another unit on the same contract lies in that
// decision's window (after the commit that added the decision), and the
// contract's acceptance criteria at this commit differ from the criteria at
// that other unit's last commit in the window. The first unit to serve the
// contract after a decision sets what the decision was carried out on; a later
// unit that serves different criteria under the same decision moved the
// contract with no decision of its own. The history comes from git, run in the
// workspace, since chant hands the hook the commit and the tree read but not
// the history.
//
// chant 0.83 reads only recordKind. chant 0.84 runs the joins and drops the
// finding; chant 0.85 carries it as a finding node, as
// plugin:decision:contract-moved; a chant with #2663 carries it as
// plugin:chud:contract-moved.

const TRAILER = { unit: 'Chud-Unit', contract: 'Chud-Contract', driver: 'Chud-Driver', evidence: 'Chud-Evidence', author: 'Chud-Author' };
const RECORD = { unit: 'design/units/{id}.json', evidence: 'design/evidence/{id}.json' };
const CONTRACTS = 'design/contracts';
/** Work items: the directory and file names of chant's work kind (work/work.kind.mjs). */
const WORK = { dir: 'work', match: /^W-[0-9]{3,}-.+\.md$/, id: /^W-[0-9]{3,}$/ };

/** The namespace of this kind's findings, plugin:chud:<code>, for a chant that reads it (chant #2663). */
export const commitJoinsName = 'chud';
export const CONTRACT_MOVED = `plugin:${commitJoinsName}:contract-moved`;
/** The same finding as chant 0.85.0 names it: by the record kind's name, since it ignores commitJoinsName. */
export const CONTRACT_MOVED_BY_KIND = `plugin:${recordKind.name}:contract-moved`;

/**
 * The code chant accepts for a finding, which depends on whether it reads
 * commitJoinsName. chant #2663 added that export and the context's list(dir)
 * together, so a context with list is a chant that names the findings after
 * commitJoinsName; without it (0.85.0) they are named after the record kind,
 * and a code in another namespace fails the join (intent-plugin-failed).
 */
export function findingCode(context, code) {
  return `plugin:${typeof context?.list === 'function' ? commitJoinsName : recordKind.name}:${code}`;
}

/** Every value of trailer `key`, compared without case as git does. */
function trailerValues(trailers, key) {
  const want = key.toLowerCase();
  return Object.entries(trailers ?? {})
    .filter(([k]) => k.toLowerCase() === want)
    .flatMap(([, values]) => values.map((v) => String(v).trim()).filter(Boolean));
}

/** A JSON record's fields, from the tree the graph reads, without its id; {} when it is not there. */
function recordFields(context, template, id) {
  const path = template.replace('{id}', id);
  const text = context.read(path);
  if (text === undefined) return {};
  let value;
  try {
    value = JSON.parse(text);
  } catch {
    throw new Error(`${path} is not JSON`);
  }
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return {};
  const { id: _id, ...rest } = value;
  return rest;
}

/**
 * chant's front matter YAML, as `chant workspace records new|amend` writes it
 * (records-write.ts toYaml): block mappings and sequences indented by two,
 * every scalar in JSON (strings double-quoted), `[]` and `{}` for empty ones.
 * A plain scalar another writer left is kept as its text. Null when there is
 * no front matter.
 */
export function frontMatter(text) {
  const m = String(text).match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/);
  if (!m) return null;
  const lines = m[1].split(/\r?\n/).filter((l) => l.trim() !== '' && !/^\s*#/.test(l));
  let i = 0;
  const indent = (l) => l.match(/^ */)[0].length;
  const scalar = (s) => {
    const v = s.trim();
    if (v === '[]') return [];
    if (v === '{}') return {};
    try {
      return JSON.parse(v);
    } catch {
      return v.length >= 2 && v.startsWith("'") && v.endsWith("'") ? v.slice(1, -1).replace(/''/g, "'") : v;
    }
  };
  const KEY = /^("(?:[^"\\]|\\.)*"|[^\s"'#:-][^:]*?)\s*:(?:\s+(.*))?$/;
  const key = (s) => (s.startsWith('"') ? JSON.parse(s) : s);
  const isItem = (l, at) => indent(l) === at && /^-(\s|$)/.test(l.slice(at));
  function block(at) {
    if (i >= lines.length || indent(lines[i]) !== at) return null;
    return isItem(lines[i], at) ? seq(at) : map(at);
  }
  function map(at) {
    const out = {};
    while (i < lines.length && indent(lines[i]) === at && !isItem(lines[i], at)) {
      const kv = lines[i].slice(at).match(KEY);
      i++;
      if (!kv) continue;
      if (kv[2] !== undefined && kv[2].trim() !== '') out[key(kv[1])] = scalar(kv[2]);
      else out[key(kv[1])] = block(at + 2) ?? (i < lines.length && isItem(lines[i], at) ? seq(at) : null);
    }
    return out;
  }
  function seq(at) {
    const out = [];
    while (i < lines.length && isItem(lines[i], at)) {
      const rest = lines[i].slice(at + 1).trim();
      if (rest === '') {
        i++;
        out.push(block(at + 2));
      } else if (KEY.test(rest) && !/^["'\[{]/.test(rest)) {
        // A mapping that starts on the dash line: read it as if the dash were indentation.
        lines[i] = `${' '.repeat(at + 2)}${rest}`;
        out.push(map(at + 2));
      } else {
        i++;
        out.push(scalar(rest));
      }
    }
    return out;
  }
  const value = map(0);
  return value && typeof value === 'object' ? value : null;
}

/** Each work item's front matter in the tree the graph reads that is one of chud's units (it has x-chud), by path. Needs context.list. */
const workCache = new WeakMap();
function workUnits(context) {
  if (typeof context?.list !== 'function') return [];
  // chant builds a context for each commit, with the same read function for one graph: the scan is done once per graph.
  const cacheKey = typeof context.read === 'function' ? context.read : null;
  if (cacheKey && workCache.has(cacheKey)) return workCache.get(cacheKey);
  const found = [];
  for (const entry of context.list(WORK.dir) ?? []) {
    const name = entry.split('/').at(-1);
    if (!WORK.match.test(name)) continue;
    const text = context.read(entry.includes('/') ? entry : `${WORK.dir}/${entry}`);
    const data = text === undefined ? null : frontMatter(text);
    if (data && typeof data.id === 'string' && data['x-chud'] && typeof data['x-chud'] === 'object') found.push({ path: entry, data });
  }
  if (cacheKey) workCache.set(cacheKey, found);
  return found;
}

/** A work item's fields as the joined unit: chud's x-chud, with chant's state and title. */
const workFields = (w) => ({ ...w.data['x-chud'], state: w.data.state, title: w.data.title, record: w.path });

export function commitJoins(commit, context) {
  const t = commit.trailers ?? {};
  const works = workUnits(context);
  // The records first: the work item whose x-chud.result.commit is this commit made it.
  const named = works.find((w) => w.data['x-chud'].result?.commit === commit.sha);
  let unitId;
  let contractId;
  let evidence;
  let unit;
  let serves;
  if (named) {
    const x = named.data['x-chud'];
    unitId = named.data.id;
    contractId = x.contract?.id ?? x.driver?.id;
    serves = x.contract ? 'contract' : x.driver ? 'driver' : null;
    evidence = [...new Set(Array.isArray(x.evidence) ? x.evidence.map(String) : [])];
    unit = { ...workFields(named), id: unitId };
  } else {
    [unitId] = trailerValues(t, TRAILER.unit);
    serves = trailerValues(t, TRAILER.contract).length ? 'contract' : trailerValues(t, TRAILER.driver).length ? 'driver' : null;
    [contractId] = serves === 'contract' ? trailerValues(t, TRAILER.contract) : trailerValues(t, TRAILER.driver);
    evidence = [...new Set(trailerValues(t, TRAILER.evidence))];
    if (unitId) {
      const w = WORK.id.test(unitId) ? works.find((x) => x.data.id === unitId) : null;
      unit = { ...(w ? workFields(w) : WORK.id.test(unitId) ? {} : recordFields(context, RECORD.unit, unitId)), id: unitId };
    }
  }
  const out = {};
  if (unit) out.unit = unit;
  if (contractId) out.contract = { id: contractId };
  if (evidence.length) out.evidence = evidence.map((hash) => ({ ...recordFields(context, RECORD.evidence, hash), id: hash }));
  if (trailerValues(t, TRAILER.author).length) out.authorship = [TRAILER.author];
  if (unitId && serves === 'contract') {
    const found = contractMoved(commit.sha, unitId, contractId, findingCode(context, 'contract-moved'));
    if (found) out.findings = [found];
  }
  return out;
}

// ---------------------------------------------------------------- the finding

/** The workspace root: the directory above this file's when it holds chant.workspace.json, else the nearest one above the cwd. */
function workspaceRoot() {
  const above = dirname(dirname(fileURLToPath(import.meta.url)));
  if (existsSync(join(above, 'chant.workspace.json'))) return above;
  for (let dir = process.cwd(); ; dir = dirname(dir)) {
    if (existsSync(join(dir, 'chant.workspace.json'))) return dir;
    if (dirname(dir) === dir) return null;
  }
}

/** The decisions directory, from the workspace root: this file's own when it is in the workspace, else decisions/. */
function decisionsDir(root) {
  const rel = relative(root, dirname(fileURLToPath(import.meta.url)));
  return rel && !rel.startsWith('..') ? rel.split(sep).join('/') : 'decisions';
}

const unquote = (s) => {
  const v = String(s ?? '').trim();
  if (v.startsWith('"') && v.endsWith('"') && v.length >= 2) {
    try {
      return JSON.parse(v);
    } catch {
      return v.slice(1, -1);
    }
  }
  if (v.startsWith("'") && v.endsWith("'") && v.length >= 2) return v.slice(1, -1).replace(/''/g, "'");
  return v;
};
const flowList = (s) => (/^\[.*\]$/.test(s.trim()) ? s.trim().slice(1, -1).split(',').map(unquote).filter(Boolean) : []);

/**
 * The fields of a decision's front matter this hook reads: id, state,
 * supersedes (ids), constrains (chant's) and x-chud.constrains (chud's own,
 * where contract ids go). The records are YAML as the design app writes them
 * (block lists, one scalar per line); anything else is skipped.
 */
export function decisionFields(text) {
  const m = String(text).match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return null;
  const out = { id: null, state: null, supersedes: [], constrains: [] };
  let top = null;
  let sub = null;
  for (const line of m[1].split(/\r?\n/)) {
    const key = line.match(/^([A-Za-z0-9_][A-Za-z0-9_-]*):(?:\s+(.*))?$/);
    if (key) {
      [top, sub] = [key[1], null];
      const value = key[2] ?? '';
      if (top === 'id') out.id = unquote(value);
      if (top === 'state') out.state = unquote(value);
      if (top === 'constrains') out.constrains.push(...flowList(value));
      continue;
    }
    const nested = line.match(/^ {2}([A-Za-z0-9_][A-Za-z0-9_-]*):(?:\s+(.*))?$/);
    if (nested) {
      sub = nested[1];
      if (top === 'x-chud' && sub === 'constrains') out.constrains.push(...flowList(nested[2] ?? ''));
      continue;
    }
    const item = line.match(/^\s*-\s+(.*)$/);
    if (!item) continue;
    if (top === 'constrains' || (top === 'x-chud' && sub === 'constrains')) out.constrains.push(unquote(item[1]));
    else if (top === 'supersedes') {
      const d = item[1].match(/^decision:\s*(.*)$/);
      if (d) out.supersedes.push(unquote(d[1]));
    }
  }
  return out.id ? out : null;
}

/** A contract's acceptance criteria, as `[id] text` lines, and the id it supersedes. */
export function contractFields(text) {
  const m = String(text).match(/^---\r?\n([\s\S]*?)\r?\n---/);
  const supersedes = m?.[1].match(/^supersedes:\s*(.+)$/m)?.[1];
  return {
    supersedes: supersedes && unquote(supersedes) !== 'null' ? unquote(supersedes) : null,
    criteria: [...String(text).matchAll(/^- \[(\w+)\] (.+)$/gm)].map((x) => ({ id: x[1], text: x[2].trim() })),
  };
}

/**
 * Whether the unit commit `sha` moved its contract inside a decision's window
 * (see the top of this file). Returns the finding, with `code` (the one the
 * running chant accepts, findingCode), or null. Never throws: when git can't
 * answer (no workspace, no repository, a shallow history), there is no
 * finding and the joins stand.
 */
export function contractMoved(sha, unitId, contractId, code = CONTRACT_MOVED) {
  try {
    const root = workspaceRoot();
    if (!root) return null;
    const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'], maxBuffer: 64 * 1024 * 1024 });
    const show = (rev, path) => {
      try {
        return git('show', `${rev}:./${path}`);
      } catch {
        return undefined;
      }
    };
    const contractFile = (rev, id) => git('ls-tree', '--name-only', rev, '--', `${CONTRACTS}/`).split('\n').find((p) => {
      const name = p.split('/').at(-1);
      return name === `${id}.md` || (name.startsWith(`${id}-`) && name.endsWith('.md'));
    });
    const contractAt = (rev, id) => {
      const file = contractFile(rev, id);
      const text = file && show(rev, file);
      return text === undefined ? null : contractFields(text);
    };

    // The contract and the versions it replaces, as the tree at the commit has them.
    const here = contractAt(sha, contractId);
    if (!here) return null;
    const chain = [contractId];
    for (let c = here; c?.supersedes && !chain.includes(c.supersedes) && chain.length < 20; c = contractAt(sha, c.supersedes)) chain.push(c.supersedes);

    // The decisions in force at the commit that constrain the contract.
    const dir = decisionsDir(root);
    const match = new RegExp(recordKind.location.match);
    const decisions = git('ls-tree', '--name-only', sha, '--', `${dir}/`).split('\n').filter((p) => match.test(p.split('/').at(-1)))
      .map((file) => ({ file, ...decisionFields(show(sha, file) ?? '') }))
      .filter((d) => d.id);
    const superseded = new Set(decisions.flatMap((d) => d.supersedes));
    const governing = decisions.filter((d) => d.state !== 'withdrawn' && !superseded.has(d.id) && d.constrains.some((c) => chain.includes(c)));

    const criteriaKey = (c) => c.criteria.map((k) => `[${k.id}] ${k.text}`).join('\n');
    for (const d of governing) {
      const added = git('log', '-1', '--diff-filter=A', '--format=%H', sha, '--', `./${d.file}`).trim();
      if (!added) continue;
      // The unit commits in the window before this one, oldest first.
      const window = git('log', '--reverse', '--format=%H%x09%(trailers:key=Chud-Unit,valueonly,separator=%x2C)%x09%(trailers:key=Chud-Contract,valueonly,separator=%x2C)', `${added}..${sha}`)
        .split('\n').filter(Boolean).map((l) => l.split('\t')).map(([commit, unit, contract]) => ({ commit, unit: unit?.trim(), contract: contract?.trim() }))
        .filter((c) => c.commit !== sha && c.unit && c.unit !== unitId && chain.includes(c.contract));
      if (!window.length) continue;
      const first = window[0];
      const last = window.filter((c) => c.unit === first.unit).at(-1);
      const before = contractAt(last.commit, last.contract);
      if (!before || criteriaKey(before) === criteriaKey(here)) continue;
      const ids = [...new Set([...before.criteria, ...here.criteria].map((k) => k.id))];
      const changed = ids.filter((id) => before.criteria.find((k) => k.id === id)?.text !== here.criteria.find((k) => k.id === id)?.text);
      return {
        code,
        message: `${unitId}'s commit ${sha.slice(0, 8)} serves ${contractId} with criteria that differ from those ${first.unit} served inside ${d.id}'s window (${changed.join(', ')} changed), and no decision since ${d.id} records the change`,
        refs: [unitId, contractId, d.id, first.unit, last.commit],
      };
    }
    return null;
  } catch {
    return null;
  }
}

