/**
 * The Machine that serves the fly site's release (fly.ts declares the rest
 * of the app): a Node image, the app's data Volume mounted at /data, and the
 * app on port 8080 behind Fly's proxy. A release adds its files, its start
 * command and its commit (@intentius/chud-runtime's fly-site.mjs).
 */
import { Machine, MachineConfig, MachineGuest, MachineMount, MachinePort, MachineService } from "@intentius/chant-lexicon-fly";

export const guest = new MachineGuest({ cpu_kind: "shared", cpus: 1, memory_mb: 256 });
export const dataMount = new MachineMount({ volume: "data", path: "/data" });
export const https = new MachinePort({ port: 443, handlers: ["tls", "http"] });
export const http = new MachinePort({ port: 80, handlers: ["http"] });
export const web = new MachineService({ protocol: "tcp", internal_port: 8080, ports: [https, http] });

export const server = new Machine({
  name: "web",
  region: "iad",
  config: new MachineConfig({
    image: "node:22-slim",
    guest,
    mounts: [dataMount],
    services: [web],
    env: { PORT: "8080", APP_DATA: "/data" },
  }),
});

