/**
 * The remote site, `fly` in chant.config.ts's chud.sites: a Fly app declared
 * with chant's fly lexicon. `chant build deploy --lexicon fly` serializes it
 * to Machines API requests, and a release to fly (`npm run release -- --env
 * fly`) applies them with the lexicon's applier, flyApply: the App, the Volume
 * the app's data lives on, a shared IPv4, the Secret, and the Machine in
 * fly-machine.ts, which the release puts its app directory, start command and
 * commit on (@intentius/chud-runtime's fly-site.mjs).
 *
 * The same declarations apply to a real Fly org (FLY_API_TOKEN, and FLY_ORG
 * for the org) or to mudflaps, the Machines API emulator, when
 * FLY_FLAPS_BASE_URL points at it. Fly app names are global: the name is the
 * app's slug (../app-name.ts); change it before the first release to a real
 * org if it is taken.
 *
 * No secret value is in the repo. APP_SECRET's value comes from the
 * environment at release time (CHUD_FLY_APP_SECRET); without it, the release
 * checks the app already has it (`fly secrets set APP_SECRET=...`) and
 * refuses otherwise.
 */
import { App, Fly, IPAddress, Secret, Volume } from "@intentius/chant-lexicon-fly";
import { FlySite } from "@intentius/chud-runtime/lexicon";
import { appSlug } from "../app-name.ts";

const name = appSlug;
const region = "iad";

export const flyApp = new App({ name, org_slug: Fly.OrgSlug });

/** The app's data (APP_DATA): it outlives releases, as .chud/site/data does locally. */
export const data = new Volume({ name: "data", region, size_gb: 1 });

export const publicIp = new IPAddress({ type: "shared_v4" });

export const appSecret = new Secret({ name: "APP_SECRET", value: process.env.CHUD_FLY_APP_SECRET || undefined });

/** The site, as `chant components status fly --live` observes it: the Machine (fly-machine.ts), and the release its metadata names. */
export const flySite = new FlySite({ env: "fly", app: name, machine: "web" });

