files.delivery/ops/release.op.ts:
/**
 * Release: ship what is committed on HEAD to the site.
 *
 * Check (stage HEAD, run the app's tests and every approved contract's
 * check against it, and commit an evidence record per check) → the app
 * component's build phases (deploy/app.component.ts): the app as one
 * archive, its SBOM, and the scan chant's vuln-gate judges by vulnPolicy,
 * which stops here, listing the findings, when the SBOM violates it → Plan
 * (work out the digest, which covers the evidence hashes, the artifact and
 * its SBOM's hash, and the ship-skip decision point's answer; it refuses
 * unless every approved contract has passing evidence) → the `ship` gate,
 * bound to the plan's digest → the rest of the component's deploy: upload
 * (which checks the evidence, that the plan passed the gate, and that the
 * archive and SBOM are the planned ones) → sign → verify the signature →
 * one effect per migration, each witnessed by a receipt so it fires once per
 * site → start → verify → record, which appends the release to chant's
 * component ledger.
 *
 * Every step is a typed capability of the chud lexicon (or chant's own, like
 * wait-endpoint), run through its `chudCapability` activity.
 *
 * The first run stops at the gate. `chant approve release ship --plan <digest>`
 * (or Approve in the design app) records the approval on the chant/lifecycle
 * branch, and the next run walks through. If anything changed since, the
 * fresh plan's digest differs and the run refuses.
 *
 * The gate's approval block (chant's gate approval policy): its quorum is the
 * one that ends the ship-skip point in decisions/points.yaml, and every
 * approval is also put to the Cedar policy in decisions/ship-skip.cedar.ts,
 * with the plan's ship-skip answer as context. The policy runs `log-only`:
 * its decision is recorded on each approval, and only people pass the gate.
 */
import { Op, phase, gate } from "@intentius/chant/op";
import { capabilityStep, releaseCheckStep, releaseDecisionStep, releasePhases, releasePlanStep, siteRestoreStep } from "@intentius/chud-runtime/lexicon";
import { config as chud, migrationReceipt, shipQuorum } from "@intentius/chud-runtime/release";
import { shipSkipPolicy } from "../decisions/ship-skip.cedar.ts";
import { app } from "../deploy/app.component.ts";

export { migrationReceipt };

const plan = capabilityStep(releasePlanStep(), { id: "plan" });
const shipSkip = capabilityStep(releaseDecisionStep({ name: "ship-skip" }), { id: "shipSkip" });
// The component's deploy, split at the gate: the build, SBOM and scan run before the plan, the rest after
// the gate. Named consts, since chant's EVL004 only lets an Op spread a const.
const build = releasePhases(app, { until: "Upload" });
const ship = releasePhases(app, {
  from: "Upload",
  effects: (s) => (s.kind === "site-migrate" ? migrationReceipt(s.file as string, s.sha as string) : undefined),
});

export default Op({
  name: "release",
  overview: `Ship HEAD of ${chud.name} to the site, gated on its plan.`,
  phases: [
    phase("Check", [capabilityStep(releaseCheckStep())]),
    ...build,
    phase("Plan", [plan, shipSkip]),
    phase("Gate", [
      gate("ship", {
        plan: plan.out.digest,
        description: `Ship ${chud.name}`,
        approval: {
          quorum: shipQuorum(),
          policy: shipSkipPolicy,
          mode: "log-only",
          context: { shipSkip: shipSkip.out.said },
        },
      }),
    ]),
    ...ship,
  ],
  onFailure: [phase("Restore the previous release", [capabilityStep(siteRestoreStep())])],
});

files.delivery/ops/rollback.op.ts:
/**
 * Rollback: put the release before the one serving back on the site. Gated
 * like a release; migrations are not undone (the data stays where it is).
 * Rolling back appends the release it serves again to chant's component
 * ledger, under the plan digest it first shipped with. The steps are typed
 * capabilities of the chud lexicon.
 */
import { Op, phase, gate } from "@intentius/chant/op";
import { capabilityStep, rollbackPlanStep, siteRollbackStep } from "@intentius/chud-runtime/lexicon";
import { app } from "../deploy/app.component.ts";

const plan = capabilityStep(rollbackPlanStep(), { id: "plan" });

export default Op({
  name: "rollback",
  overview: "Serve the previous release again.",
  phases: [
    phase("Plan", [plan]),
    phase("Gate", [gate("rollback", { plan: plan.out.digest, description: "Roll back to the previous release" })]),
    phase("Roll back", [capabilityStep(siteRollbackStep(), { component: app.name })]),
  ],
});

