// Check for C-001 (contracts/C-001-notes.md). Runs against APP_URL.
import { test } from 'node:test';
import assert from 'node:assert/strict';

const url = process.env.APP_URL ?? 'http://127.0.0.1:3000';
const post = (body) => fetch(`${url}/api/notes`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ body }) });

test('a1: posting a note answers 201 with the saved note', async () => {
  const res = await post('first');
  assert.equal(res.status, 201);
  assert.equal((await res.json()).body, 'first');
});

test('a2: the newest note is listed first', async () => {
  await post('older');
  await post('newer');
  const notes = await (await fetch(`${url}/api/notes`)).json();
  assert.equal(notes[0].body, 'newer');
});

test('a3: an empty note is refused with 400', async () => {
  assert.equal((await post('   ')).status, 400);
});

files.design/evidence/evidence.kind.mjs:
// chud's evidence record kind (jhgaylor/chud#78), data only: no imports, no
// code. chant reads it from 0.86.0 on (INTENTIUS/chant#2684, ws-053):
//
//   chant workspace records --json
//
// Each record is one run of one contract's check, a JSON file named for the
// sha256 of its bytes. The id is that hash (idFrom), the same string a pin of
// the file holds. A file whose name is not the hash of its bytes stays valid
// in chant's read and carries the warning asset-drift; chud refuses it as
// evidence by reading that warning. Evidence has no lifecycle and supersedes
// nothing.
//
// evidence.schema.json is @intentius/chud-runtime's schemas/evidence.schema.json
// byte for byte, and ../schemas/defs.schema.json is its defs.schema.json;
// chud's tests fail when they drift. chud writes these files itself (chant's
// write verbs refuse JSON kinds) and reads each write back through chant.
export const recordKind = {
  name: "evidence",
  location: { dir: ".", match: "^[0-9a-f]{64}\\.json$" },
  format: "json",
  schema: {
    id: "https://schemas.intentius.dev/chud-runtime/v0/evidence.schema.json",
    path: "evidence.schema.json",
    refs: [{ id: "https://schemas.intentius.dev/chud-runtime/v0/defs.schema.json", path: "../schemas/defs.schema.json" }],
  },
  idFrom: "sha256",
};

