{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://schemas.intentius.dev/chud-runtime/v0/evidence.schema.json",
  "title": "Evidence",
  "description": "evidence/<sha256>.json: the result of one run of one contract's check, named by the sha256 of the file's bytes. Written only by runners: the design app's check job, and the release and upgrade Ops' Check phases (#5).",
  "type": "object",
  "required": [
    "contract",
    "check_sha",
    "commit",
    "tree",
    "runner",
    "ok",
    "criteria",
    "output",
    "at"
  ],
  "properties": {
    "contract": {
      "type": "object",
      "required": [
        "id",
        "sha"
      ],
      "additionalProperties": false,
      "properties": {
        "id": {
          "$ref": "defs.schema.json#/definitions/contractId"
        },
        "sha": {
          "$ref": "defs.schema.json#/definitions/sha256"
        }
      },
      "description": "The contract checked, and its sha (title, body and check) when it ran."
    },
    "check_sha": {
      "$ref": "defs.schema.json#/definitions/sha256",
      "description": "sha256 of the check file that ran."
    },
    "commit": {
      "description": "The commit tested, or null when the working tree was tested and differed from HEAD in the app or the check.",
      "type": [
        "string",
        "null"
      ],
      "pattern": "^[0-9a-f]{40}$"
    },
    "tree": {
      "$ref": "defs.schema.json#/definitions/gitId",
      "description": "The git tree id of the app directory as tested. With contract.sha it names what the evidence is about: a release accepts evidence for the tree its commit holds."
    },
    "runner": {
      "type": "object",
      "required": [
        "kind"
      ],
      "additionalProperties": false,
      "properties": {
        "kind": {
          "enum": [
