                "page": {
                  "type": [
                    "string",
                    "null"
                  ],
                  "description": "The page an element or text was looked for on."
                },
                "ok": {
                  "type": "boolean"
                },
                "detail": {
                  "type": "string",
                  "maxLength": 500
                }
              }
            }
          }
        }
      },
      "description": "Structural checks run for the contract's reference assets (design-doc.mjs): per referenced section, each route, element and text it declares, and whether the running app has it. Their results count toward the criteria."
    }
  },
  "patternProperties": {
    "^x-": true
  },
  "additionalProperties": false
}

