{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://schemas.intentius.dev/chud-runtime/v0/session.schema.json",
  "title": "Design session",
  "description": "sessions/S-NNNN.json: a facilitated review, written by the design app. It records who took part, what was reviewed (a contract, a driver, a driver's split or a release gate, with the evidence hashes and any screenshot or recording), what a facilitating agent prepared, and what the people decided: approvals, decisions, comments, and follow-up contracts drafted. The facilitator prepares; only participants' actions write approvals, decisions, comments, follow-ups or the closing. Once closed it never changes: `seal` is chant's seal for a JSON session kind, the sha256 of the file's text without its top-level `seal` member, and chant workspace records checks it on every read (session-seal-mismatch). In a repo whose chant.workspace.json does not declare the session kind, it is the sha256 of the record without `seal` as canonical JSON, and chud checks it.",
  "type": "object",
  "required": [
    "id",
    "title",
    "status",
    "opened_by",
    "opened_at",
    "participants",
    "reviewed",
    "approvals",
    "decisions",
    "comments",
    "follow_ups"
  ],
  "properties": {
    "id": {
      "$ref": "defs.schema.json#/definitions/sessionId"
