      "description": "What the work is, in a few words.",
      "type": "string",
      "minLength": 1
    },
    "state": {
      "description": "open: nobody has started it. in-progress: someone has. done: finished, with its proof in evidence. dropped: not going to happen. done and dropped are closed.",
      "enum": [
        "open",
        "in-progress",
        "done",
        "dropped"
      ]
    },
    "implements": {
      "description": "The decisions this work carries out, by id. May be empty. chant workspace records warns work-implements-undecided when one is still proposed.",
      "type": "array",
      "items": {
        "$ref": "#/definitions/decisionId"
      },
      "uniqueItems": true
    },
    "needs": {
      "description": "The work items that must be done before this one is ready, by id. May be empty.",
      "type": "array",
      "items": {
        "$ref": "#/definitions/workId"
      },
      "uniqueItems": true
    },
    "constrains": {
      "description": "What this work touches, in the grammar a decision's constrains uses: issues (owner/repo#n), decision ids, workspace members (member:<name>) or workspace paths (path:<path>). At least one entry.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "pattern": "^([A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+#[0-9]+|[a-z][a-z0-9]{0,15}-[0-9]{3,}|member:[a-z0-9][a-z0-9-]{0,39}|path:(?!/)(?!(?:[^/]*/)*\\.{1,2}(?:/|$))(?!.*//)[^\\\\\\u0000-\\u001f]*[^/\\\\\\u0000-\\u001f])$"
      }
    },
    "evidence": {
      "description": "The proof of done: public links, or workspace files pinned by the hash of their bytes (chant workspace records pin <path>). May be empty while the work is open; a done item with none gets the warning work-done-unpinned.",
      "type": "array",
      "items": {
        "oneOf": [
          {
            "$ref": "#/definitions/evidenceLink"
          },
          {
            "$ref": "#/definitions/evidencePin"
          }
        ]
      }
    },
    "owner": {
      "description": "Who has taken the work: a principal, such as a forge login or an agent's name. Null or absent while nobody has.",
      "type": [
        "string",
        "null"
      ],
      "minLength": 1
    },
    "opened_on": {
      "description": "When the item was written, as YYYY-MM-DD. Quoted, so YAML reads it as a string.",
      "type": "string",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
    },
    "closed_on": {
      "description": "When the item became done or dropped, as YYYY-MM-DD. chant workspace records warns work-closed-without-date when a closed item has none.",
      "type": [
        "string",
        "null"
      ],
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
    },
    "source": {
      "description": "Where the work came from: a gap the intent graph reported, an issue, or the workspace itself.",
      "oneOf": [
        {
          "$ref": "#/definitions/sourceGap"
        },
        {
          "$ref": "#/definitions/sourceIssue"
        },
        {
          "$ref": "#/definitions/sourceWorkspace"
        }
      ]
    },
    "supersedes": {
      "description": "Earlier work items this one replaces. Takes effect once this item is done or dropped.",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "work"
        ],
        "properties": {
          "work": {
            "$ref": "#/definitions/workId"
          }
        }
      }
    },
    "x-chud": {
      "description": "chud's dispatch fields for a work item that is one of its units (jhgaylor/chud#78): what the unit serves, who ran it and how, where its work went, and why it did not finish. chud's runtime writes it through chant workspace records new and amend; the unit board and chud status read it back from chant workspace records --json.",
      "type": "object",
      "additionalProperties": false,
      "patternProperties": {
        "^x-": {}
      },
      "required": [
        "role",
        "agent",
        "scope",
        "context_hash",
        "base_commit",
        "result",
        "evidence",
        "opened_at"
      ],
      "properties": {
        "role": {
          "enum": [
            "formalize",
            "build",
            "manual",
            "split"
          ],
          "description": "What kind of work: a formalizer run (writes the contract's check), a builder run (changes the app), manual work recorded from the design app, or a splitter run (proposes draft contracts for a driver)."
        },
        "contract": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "id",
            "sha"
          ],
          "properties": {
            "id": {
              "type": "string",
              "pattern": "^C-[0-9]{3,}$"
            },
            "sha": {
              "type": "string",
              "pattern": "^[0-9a-f]{64}$"
            }
          },
          "description": "The contract the unit serves, and the sha256 of its file when the unit opened. Every unit but a split has one."
        },
        "driver": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "id",
            "sha"
          ],
          "properties": {
            "id": {
              "type": "string",
              "pattern": "^D-[0-9]{3,}$"
            },
            "sha": {
              "type": "string",
              "pattern": "^[0-9a-f]{64}$"
            }
          },
          "description": "split: the driver the unit splits, and the sha256 of its file when the unit opened."
        },
        "agent": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "name",
            "model",
            "runtime"
          ],
          "properties": {
            "name": {
              "type": "string",
              "minLength": 1,
              "description": "The agent, or the person for manual work."
            },
            "model": {
              "type": [
                "string",
                "null"
              ]
            },
            "runtime": {
              "type": [
                "string",
                "null"
              ]
            }
          }
        },
        "scope": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          },
          "description": "The paths the unit's work covers, from the workspace root. Done work under them is committed; not_done work is kept at refs/chud/units/<id> and removed from the working tree. The item's constrains names them as path: entries."
        },
        "by": {
          "type": "string",
          "minLength": 1,
          "description": "Who started the unit."
        },
        "context_hash": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[0-9a-f]{64}$",
          "description": "sha256 of the context bundle the agent was given (design/context/<hash>.json). null for manual work."
        },
        "base_commit": {
          "type": "string",
          "pattern": "^[0-9a-f]{40}$",
          "description": "HEAD when the unit opened."
        },
        "lease": {
          "type": [
            "object",
            "null"
          ],
          "additionalProperties": false,
          "required": [
            "id",
            "worker"
          ],
          "properties": {
            "id": {
              "type": "string",
              "minLength": 1
            },
            "worker": {
              "type": "string",
              "minLength": 1
            }
          },
          "description": "The dispatch lease the unit runs under (the chud/leases branch): its claim id and the worker holding it. Absent for work the design app started."
        },
        "slice": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "tier": {
              "type": [
                "string",
                "null"
              ]
            }
          },
          "description": "The slice a dispatcher or the design app built: the tier it ran at."
        },
        "result": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "commit",
            "ref"
          ],
          "properties": {
            "commit": {
              "type": [
                "string",
                "null"
              ],
              "pattern": "^[0-9a-f]{40}$"
            },
            "ref": {
              "type": [
                "string",
                "null"
              ]
            }
          },
          "description": "Where the work is. done: the commit holding it (null when the unit changed nothing). not_done: the snapshot commit and refs/chud/units/<id>. Both null while open. The intent graph joins a commit to the unit through this field."
        },
        "evidence": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "pattern": "^[0-9a-f]{64}$"
          },
          "description": "The evidence records (design/evidence/<sha256>.json) the unit cites, by hash. The item's evidence pins the same files by path and sha256."
        },
        "not_done": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "reason": {
              "type": [
                "string",
                "null"
              ],
              "pattern": "^[a-z][a-z0-9-]*$",
              "maxLength": 60
            }
          },
          "description": "Set when the unit closed not done (the item is dropped). reason: one word a program can read, lease-lost or lease-expired, or null."
        },
        "corrects": {
          "type": "string",
          "pattern": "^(U-[0-9]{4,}|W-[0-9]{3,})$",
          "description": "The earlier unit this one fixes."
        },
        "from": {
          "type": "string",
          "pattern": "^(U-[0-9]{4,}|W-[0-9]{3,})$",
          "description": "The not_done unit whose kept work this unit started from."
        },
        "superseded_by": {
          "type": "string",
          "pattern": "^C-[0-9]{3,}$",
          "description": "Set when the unit closed not done because its contract was superseded: the version that replaced it."
        },
        "note": {
          "type": "string",
          "description": "What the unit is for, or why it closed as it did."
        },
        "opened_at": {
          "type": "string",
          "description": "When the unit opened, as an ISO 8601 date-time."
        },
        "closed_at": {
          "type": "string",
          "description": "When the unit closed, as an ISO 8601 date-time."
        }
      }
    }
  },
  "definitions": {
    "workId": {
      "type": "string",
      "pattern": "^W-[0-9]{3,}$"
    },
    "decisionId": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9]{0,15}-[0-9]{3,}$"
    },
    "issueRef": {
      "type": "string",
      "pattern": "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+#[0-9]+$"
    },
    "workspacePath": {
      "description": "A path from the workspace root, with / separators: no leading /, no . or .. segment, no empty segment, no backslash and no trailing /.",
      "type": "string",
      "pattern": "^(?!/)(?!(?:[^/]*/)*\\.{1,2}(?:/|$))(?!.*//)[^\\\\\\u0000-\\u001f]*[^/\\\\\\u0000-\\u001f]$"
    },
    "evidenceLink": {
      "description": "A public link.",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "title",
        "url"
      ],
      "properties": {
        "title": {
          "type": "string",
          "minLength": 1
        },
        "url": {
          "type": "string",
          "pattern": "^https://"
        },
        "as_of": {
          "description": "When the linked text was read, as an ISO 8601 timestamp. Lets a reader flag evidence that changed afterwards.",
          "type": [
            "string",
            "null"
          ]
        },
        "sha256": {
          "description": "Hex SHA-256 of the linked content, once evidence is pinned by hash (#2555). Null until then.",
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[0-9a-f]{64}$"
        }
      }
    },
    "evidencePin": {
      "description": "A file in the workspace, pinned by the hash of its bytes. chant workspace records reports a file that changed or went missing since.",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "title",
        "path",
        "sha256"
      ],
      "properties": {
        "title": {
          "type": "string",
          "minLength": 1
        },
        "path": {
          "description": "The file, from the workspace root. It sits inside a member, such as design/screens/home.json.",
          "$ref": "#/definitions/workspacePath"
        },
        "sha256": {
          "description": "Hex SHA-256 of the file's bytes when the work was done. chant workspace records pin <path> prints it.",
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        },
        "as_of": {
          "description": "When the file was read, as an ISO 8601 timestamp.",
          "type": [
            "string",
            "null"
          ]
        }
      }
    },
    "sourceGap": {
      "description": "The gap the work closes, as chant workspace graph --intent reported it (#2683). The honest way to finish the work is to make the finding stop firing on the region; graph --intent warns work-done-gap-open on a done item whose finding still fires.",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "finding",
        "region"
      ],
      "properties": {
        "finding": {
          "description": "The finding's code: one of chant's intent finding codes, or a plugin's plugin:<name>:<code>.",
          "anyOf": [
            {
              "enum": [
                "intent-commit-undecided",
                "intent-commit-bare",
                "intent-pin-drifted",
                "intent-pin-missing",
                "intent-artifact-unpinned",
                "intent-decision-superseded-live",
                "intent-decision-provisional",
                "intent-constraint-coarse",
                "intent-constraint-lost",
                "intent-evidence-unpinned",
                "intent-trailer-unverified",
                "intent-region-unconstrained",
                "intent-decision-unimplemented",
                "intent-work-blocked",
                "intent-work-open-decided-code"
              ]
            },
            {
              "type": "string",
              "pattern": "^plugin:[^:\\s]+:[a-z0-9]+(-[a-z0-9]+)*$"
            }
          ]
        },
        "region": {
          "description": "The region the finding fired on, as graph --intent takes it: a workspace path, path:line or path:start-end, or . for the whole workspace.",
          "type": "string",
          "pattern": "^(\\.|(?!/)(?!(?:[^/]*/)*\\.{1,2}(?:/|:|$))(?!.*//)[^\\\\\\u0000-\\u001f:]*[^/\\\\\\u0000-\\u001f:](:[1-9][0-9]*(-[1-9][0-9]*)?)?)$"
        },
        "decision": {
          "description": "The decision the finding concerned, when it concerned one.",
          "$ref": "#/definitions/decisionId"
        },
        "artifact": {
          "description": "The artifact the finding concerned, from the workspace root, when it concerned one.",
          "$ref": "#/definitions/workspacePath"
        }
      }
    },
    "sourceIssue": {
      "description": "An issue that asked for the work.",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "issue"
      ],
      "properties": {
        "issue": {
          "$ref": "#/definitions/issueRef"
        },
        "row": {
          "description": "A row of the issue's table the work comes from, verbatim, when there is one.",
          "type": "string"
        }
      }
    },
    "sourceWorkspace": {
      "description": "Work that came up in the workspace, such as in a member's own session, with no issue behind it.",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "kind",
        "member"
      ],
      "properties": {
        "kind": {
          "const": "workspace"
        },
        "member": {
          "description": "The workspace member the work came up in, by its name in the declaration.",
          "type": "string",
          "pattern": "^[a-z0-9][a-z0-9-]{0,39}$"
        },
        "session": {
          "description": "The id of the session the work came up in, as the member names it. Null or absent when there was none.",
          "type": [
            "string",
            "null"
          ],
          "minLength": 1
        },
        "issue": {
          "description": "An issue the work relates to, when there is one.",
          "$ref": "#/definitions/issueRef"
        }
      }
    }
  }
}
